const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate polygon for Poyang Lake, China.
  // This is a simplified boundary for the purpose of the analysis.
  const poyangLake = ee.Geometry.Polygon(
    [[[115.68812604929828, 29.831776991196414],
      [116.82093854929828, 29.813088190807563],
      [116.83963483836175, 28.53753733072224],
      [115.69460297800922, 28.52554707107775]]]);

  const date1_start = '2022-07-01';
  const date1_end = '2022-07-15'; // Window around July 10
  const date2_start = '2022-08-20';
  const date2_end = '2022-08-31'; // Window around August 27

  const SCALE = 30; // Use a coarser scale to avoid memory issues for large lakes, but still reasonable.
                   // Sentinel-2 is 10m, so 30m is a good compromise for area calculation.

  // Sentinel-2 cloud masking function
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
                .select(['B2', 'B3', 'B4', 'B8']) // Select relevant bands and scale
                .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDWI and create water mask
  function calculateWaterMask(image) {
    // NDWI = (Green - NIR) / (Green + NIR)
    // Sentinel-2: B3 = Green, B8 = NIR
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    // Threshold for water detection. NDWI > 0 is a common threshold for water.
    const waterMask = ndwi.gt(0.2).rename('Water'); // Using 0.2 for clear water
    return waterMask.updateMask(waterMask); // Mask out non-water pixels
  }

  // Function to process an image collection for a given date range
  async function processCollection(startDate, endDate, label) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(poyangLake)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Pre-filter less cloudy images

    // Check if collection is empty
    const collectionSize = await collection.size().getInfo();
    console.log(`${label} Images found: ${collectionSize}`);
    if (collectionSize === 0) {
      return null;
    }

    // Apply cloud mask and calculate water mask
    const processedCollection = collection.map(maskS2clouds).map(calculateWaterMask);

    // Get the median water mask for the period
    const waterImage = processedCollection.median().clip(poyangLake);

    // Calculate valid pixel count for the water mask (to check for C2)
    const waterPixelsCount = await waterImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: poyangLake,
      scale: SCALE,
      maxPixels: 1e9
    }).get('Water').getInfo();

    if (waterPixelsCount === null || waterPixelsCount === 0) {
      console.log(`${label} No valid water pixels after processing.`);
      return 0; // Return 0 area if no valid water pixels
    }

    // Calculate surface water area
    // Pixel area in square meters: SCALE * SCALE
    const pixelAreaSqM = ee.Number(SCALE).multiply(SCALE);

    const waterAreaSqM = await waterImage.multiply(pixelAreaSqM)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: poyangLake,
        scale: SCALE,
        maxPixels: 1e9
      }).get('Water').getInfo();

    if (waterAreaSqM === null || waterAreaSqM === undefined) {
      return 'C3'; // Calculation failed
    }

    return waterAreaSqM / 1e6; // Convert square meters to square kilometers
  }

  let area1, area2;

  console.log("Processing July 2022 data...");
  area1 = await processCollection(date1_start, date1_end, 'July 2022');

  console.log("Processing August 2022 data...");
  area2 = await processCollection(date2_start, date2_end, 'Aug 2022');

  // Check for C1 (Empty Collection) or C3 (Calculation Failure)
  if (area1 === null || area2 === null) {
    console.log("One or both collections were empty after initial filter (C1).");
    console.log("C1");
    return;
  }
  if (area1 === 'C3' || area2 === 'C3') {
    console.log("Calculation failure (C3).");
    console.log("C3");
    return;
  }

  // Check for C2 (No Valid Pixels) - handled by returning 0
  if (area1 === 0 && area2 === 0) {
    console.log("No valid pixels for either period after cloud masking (C2).");
    console.log("C2");
    return;
  }
  if (area1 === 0) {
    console.log(`July 2022 Water Area: 0.00 km² (C2)`);
  } else {
    console.log(`July 2022 Water Area: ${area1.toFixed(2)} km²`);
  }
  if (area2 === 0) {
    console.log(`Aug 2022 Water Area: 0.00 km² (C2)`);
  } else {
    console.log(`Aug 2022 Water Area: ${area2.toFixed(2)} km²`);
  }

  // 5. Validation & Final Answer
  const difference = area1 - area2;
  console.log(`Difference (July - Aug): ${difference.toFixed(2)} km²`);

  if (area2 < area1) {
    console.log("A"); // Area decreased
  } else if (area2 > area1) {
    console.log("B"); // Area increased or stayed same
  } else {
    console.log("B"); // Area stayed the same
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
